const body = $input.first().json.body || {};
const complaintId     = parseInt(body.complaintId);
const closureStatus   = (body.closureStatus  || 'Partially Closed');
const followupMethod  = (body.followupMethod || 'Call');
const txnId           = body.txnId          || '';
const mobileCalled    = body.mobileCalled   || '';
const emailSubject    = body.emailSubject   || '';
const vendorTicketNo  = (body.vendorTicketNo || '').trim();
const delayMain       = body.delayMain      || '';
const delaySub        = body.delaySub       || '';
const baseRemarks     = body.remarks        || '';
const uid             = parseInt(body.uid   || 1);
const agentName       = body.agentName      || '';

const escalationLevel = parseInt(body.escalationLevel || 1);
const newClosureDate  = body.newClosureDate || '';
const closureDate     = body.closureDate    || '';
const closedBy        = (body.closedBy      || '').trim();

if (!complaintId) return [{ json: { success: false, error: 'complaintId required' } }];

const esc = v => (v || '').toString().replace(/'/g, "''");

const parts = [baseRemarks];
if (followupMethod === 'Call') {
  if (txnId) parts.push('TXN: ' + txnId);
  if (mobileCalled) parts.push('Mobile: ' + mobileCalled);
} else if (followupMethod === 'Vendor Update') {
  if (vendorTicketNo) parts.push('Vendor Ticket: ' + vendorTicketNo);
} else {
  if (emailSubject) parts.push('Subject: ' + emailSubject);
}
if (delayMain) parts.push('Delay: ' + delayMain + (delaySub ? ' - ' + delaySub : ''));
if (closureDate) parts.push('Closure Date: ' + closureDate);
if (closedBy) parts.push('Closed By: ' + closedBy);
parts.push('Source: ' + followupMethod);

const fullRemarks = esc(parts.filter(Boolean).join(' | '));

const insertLog = `INSERT INTO vmm_complaintlogs (complaintid, remarks, status, uid, created, is_deleted) VALUES (${complaintId}, '${fullRemarks}', '${esc(closureStatus)}', ${uid}, NOW(), 'No')`;

const insertEsc = ((closureStatus === 'Partially Closed' || closureStatus === 'Escalated') && newClosureDate)
  ? `INSERT INTO vmm_vendorescalations (complaintid, escalationlevel, ticketno, closuredate, uid, created, is_deleted) VALUES (${complaintId}, ${escalationLevel}, '${esc(vendorTicketNo)}', '${esc(newClosureDate)}', ${uid}, NOW(), 'No')`
  : null;

const updateTicket = (vendorTicketNo && closureStatus !== 'Partially Closed' && closureStatus !== 'Escalated')
  ? `UPDATE vmm_vendorescalations SET ticketno = '${esc(vendorTicketNo)}' WHERE id = (SELECT MAX(id) FROM vmm_vendorescalations WHERE complaintid = ${complaintId})`
  : null;

return [{ json: { insertLog, insertEsc, updateTicket, complaintId, closureStatus, closureDate, closedBy, baseRemarks } }];

// ── TEST MODE: flip to false when going live ──────────────
const TEST_MODE  = false;
const TEST_EMAIL = 'inder@openmind.in';
// ───────────────────────────────────────────────────────────

const d  = $('Build Queries').first().json;
const c  = $input.first().json;

const closureStatus = d.closureStatus || 'Closed';
const closureDate   = d.closureDate   || '';
const closedBy      = d.closedBy      || '';
const remarks       = d.baseRemarks   || '';

const complaintno = c.complaintno || '';
const productName = c.productname || 'the reported issue';
const storeName   = c.storename   || '';
const storeCode   = c.storecode   || '';
const storeEmail  = c.storeemail  || '';
const fmEmail     = c.fmemail     || '';
const fmName      = c.fmname      || '';

const subject = `Your store ticket ${complaintno} has been ${closureStatus}`;

const htmlBody = `
<div style="font-family:Arial,sans-serif;font-size:14px;line-height:1.7;max-width:600px;margin:0 auto">
  <div style="background:#1e1b4b;padding:18px 28px;border-radius:8px 8px 0 0">
    <div style="color:#a5b4fc;font-size:11px;letter-spacing:.08em;text-transform:uppercase;margin-bottom:2px">VMM Facility Management</div>
    <h2 style="color:#fff;margin:0;font-size:18px">Complaint ${closureStatus}</h2>
  </div>
  <div style="background:#fff;padding:24px 28px;border:1px solid #e2e8f0;border-top:none">
    <p style="margin:0 0 16px">Dear Store Manager,</p>
    <p style="margin:0 0 20px">
      We are pleased to inform you that your store ticket <strong>${complaintno}</strong> for
      <strong>${productName}</strong> at <strong>${storeName} (${storeCode})</strong>
      has been successfully ${closureStatus === 'Closed' ? 'closed' : closureStatus.toLowerCase()}.
      ${fmName && closureDate ? `The same was confirmed by FM <strong>${fmName}</strong> on <strong>${closureDate}</strong>.` : ''}
    </p>
    ${closedBy ? `<p style="margin:0 0 16px">Closed by: <strong>${closedBy}</strong></p>` : ''}
    ${remarks ? `<p style="margin:0 0 20px;padding:12px 14px;background:#f8fafc;border-left:3px solid #6366f1;font-size:13px"><strong>Remarks:</strong> ${remarks}</p>` : ''}
    <p style="margin:0;font-size:13px;color:#64748b">
      For any queries please reach us at
      <a href="mailto:vmm.helpdesk@openmind.in" style="color:#4f46e5">vmm.helpdesk@openmind.in</a>
      or call <strong>9711 772 722</strong>. Thank you for your cooperation.
    </p>
    <p style="margin:16px 0 0;font-size:13px">Regards,<br/><strong>VMM Helpdesk</strong><br/>9711 772 722</p>
  </div>
  <div style="padding:12px 28px;background:#f8fafc;border:1px solid #e2e8f0;border-top:none;border-radius:0 0 8px 8px;font-size:11px;color:#94a3b8">
    Open Mind Services Limited &nbsp;·&nbsp; VMM CRM &nbsp;·&nbsp; vmm.helpdesk@openmind.in
  </div>
</div>`;

const finalSubject = TEST_MODE ? `[TEST] ${subject}` : subject;
const toEmail      = TEST_MODE ? TEST_EMAIL : [storeEmail].filter(Boolean).join(',');
const ccEmails     = TEST_MODE ? ''         : [fmEmail].filter(Boolean).join(';');

return [{ json: { subject: finalSubject, htmlBody, toEmail, ccEmails } }];
